def _read_excel_fast(_src, **kwargs):
    """Lê Excel priorizando o engine calamine (4-7x mais rápido que openpyxl em arquivos
    muito estilizados), com FALLBACK automático ao openpyxl se o calamine não estiver
    disponível ou falhar. Reposiciona o buffer quando a fonte é BytesIO."""
    import pandas as _pd
    try:
        if hasattr(_src, "seek"):
            _src.seek(0)
    except Exception:
        pass
    if "engine" not in kwargs:
        try:
            return _pd.read_excel(_src, engine="calamine", **kwargs)
        except Exception:
            try:
                if hasattr(_src, "seek"):
                    _src.seek(0)
            except Exception:
                pass
    return _pd.read_excel(_src, **kwargs)


def _excelfile_fast(_src):
    """Abre um ExcelFile priorizando calamine (mais rápido), com fallback ao openpyxl."""
    import pandas as _pd
    try:
        if hasattr(_src, "seek"):
            _src.seek(0)
    except Exception:
        pass
    try:
        return _pd.ExcelFile(_src, engine="calamine")
    except Exception:
        try:
            if hasattr(_src, "seek"):
                _src.seek(0)
        except Exception:
            pass
    return _pd.ExcelFile(_src)


def _limpa_nome(x):
    """Decodifica sequências de escape do Excel (_xHHHH_) de volta ao caractere real —
    ex.: 'BARRA_x0020_DO_x0020_BUGRES' -> 'BARRA DO BUGRES'. Seguro para qualquer texto."""
    import re as _re
    _s = str(x)
    if "_x" in _s:
        try:
            _s = _re.sub(r"_x([0-9A-Fa-f]{4})_", lambda _m: chr(int(_m.group(1), 16)), _s)
        except Exception:
            pass
    return _s


def _limpa_colunas_nome(_df):
    """Aplica _limpa_nome nas colunas de nome (NO_*) de um DataFrame, sem tocar no resto.
    Só altera valores string que contêm escape (_x....), preservando nulos e demais tipos."""
    for _c in _df.columns:
        if str(_c).upper().startswith("NO_"):
            try:
                _df[_c] = _df[_c].map(lambda _v: _limpa_nome(_v) if isinstance(_v, str) and "_x" in _v else _v)
            except Exception:
                pass
    return _df


